import pathlib,json,re,html
R=pathlib.Path(__file__).resolve().parents[1];T=R/'wordpress/wp-content/themes/anz-2027';(T/'inc').mkdir(exist_ok=True)
pages=json.loads((R/'content-migration/page-summary.json').read_text(encoding='utf8'))
raw=json.loads((R/'content-migration/export-audit.json').read_text(encoding='utf8'))
available={p.stem for p in (T/'assets/media').glob('*.webp')}
copy={
721:('Rooftop gardens and terrace planting.','Bring planting, places to sit and an outdoor rhythm to your rooftop. Terrace gardens begin with the practical details: structure, waterproofing, drainage and access.','Roof use and access|Planting and planters|Watering and drainage','Can any terrace become a garden?','Suitability depends on the structure, permitted loads, waterproofing and drainage. Arrange a site review and obtain structural advice before installation.'),
1301:('Vertical planting systems and green walls.','Vertical gardens bring planting into spaces where ground area is limited. ANZ plans and installs green walls with attention to support, irrigation and continuing access for care.','Wall and support review|Plant selection|Watering and ongoing care','What should I check before adding a green wall?','Discuss light, wall condition, access, drainage and irrigation. The planting and support system should suit the site and its maintenance arrangements.'),
1303:('Garden design and installation for villas.','A villa garden should belong to its architecture and the people who use it. Connect planting, pathways and places to pause through a landscape designed around your home.','Garden layout|Planting and outdoor spaces|Installation and aftercare','Can the garden work with an existing home?','Share a site plan and photographs of the existing space. Retained planting, access, drainage and how you use the garden help define the scope.'),
1305:('Pergolas, roofing and outdoor structures.','Pergolas and fabrication define outdoor rooms. Explore shade, structure and material choices that complement your building, terrace or garden.','Design and fabrication|Roofing and material options|Installation','Which pergola materials are available?','The existing ANZ service range includes glass, wood, polycarbonate, retractable roofing, shingle roofs and Mangalore tile gazebos. Confirm current availability and structural requirements for your site.'),
1307:('Planting and landscape finishes.','A considered landscape is shaped by proportion, planting and the way a space is lived in. ANZ brings garden design and execution together for bespoke outdoor environments.','Site-specific design|Planting and material selection|Landscape execution','Where does a custom landscape begin?','Begin with the architecture, site conditions and your intended use. A detailed brief helps establish priorities and a suitable scope before materials are selected.'),
1309:('Pool planning and surrounding landscape.','Swimming pools are part of a larger outdoor setting. Discuss the pool, its surroundings and the practical systems that need to be coordinated before work begins.','Pool and landscape planning|Surrounding outdoor space|Project coordination','What pool work can ANZ undertake?','Share whether you need a new pool, an upgrade or surrounding landscaping. Confirm design, engineering, construction and equipment responsibilities in the written project scope.'),
1311:('Fountains, ponds and water features.','Fountains and ponds add a focal point to outdoor spaces. Their placement, water systems and care requirements deserve the same attention as the planting around them.','Water-feature planning|Landscape integration|Care and access considerations','What needs to be planned for a water feature?','Discuss filtration, circulation, power, cleaning access and safety. These requirements depend on the feature and should be agreed before installation.'),
1315:('Landscape design for commercial sites.','From building frontages to shared outdoor grounds, commercial landscapes must balance identity, everyday use and ongoing upkeep. ANZ brings planting and landscape execution into one coordinated scope.','Site and stakeholder brief|Hardscape and planting|Execution and maintenance planning','Can work be planned around an occupied site?','Share access restrictions, working-hour requirements and stakeholder approvals. Discuss phasing and practical constraints as part of the site assessment.'),
1317:('Watering systems for lawns and planting.','Irrigation should respond to the landscape it serves. Plan water delivery around planting zones, site conditions and practical access for inspection and maintenance.','Planting-zone assessment|Water-delivery planning|Installation and upkeep','Can irrigation be added to an existing garden?','An assessment should check available water supply, planting needs, existing lines and access. Discuss repair or new installation after reviewing the site.'),
1319:('Lawns, planting and garden beds.','Softscape brings together lawns, plants and the changing textures of a garden. ANZ selects and installs planting to suit the light, soil and use of the space.','Planting palettes|Lawns and garden beds|Installation and care','How are plants selected?','Light, soil, water availability, growth habit and maintenance needs guide the selection. Confirm species and availability when the planting schedule is prepared.'),
1321:('Paving, paths and landscape structures.','Paths, paved areas and landscape edges give a garden its shape. Coordinate materials, levels and drainage with the planting and everyday movement through the site.','Material selection|Paths and outdoor surfaces|Installation coordination','What should inform a paving choice?','Consider drainage, slip resistance, heat, access and maintenance as well as appearance. The right material depends on where and how the surface will be used.'),
1323:('Moss wall installations for interiors.','Moss wall installations bring a distinctive material quality to interiors. Explore the visual treatment, product type and care requirements for your space.','Wall and interior context|Texture and design|Installation requirements','Is the moss living or preserved?','Confirm the actual product before specifying light, water or care requirements. Living and preserved systems have different needs; ask ANZ to identify the proposed system in the quote.'),
1325:('Scheduled garden and plant maintenance.','A garden continues to evolve after installation. ANZ provides garden maintenance, with care planned around the plants, site conditions and the work your space needs.','Plant and lawn care|Pruning and watering|Site-specific maintenance','How often will the team visit?','Visit frequency and included tasks should be agreed after assessing the site. Ask for a written maintenance scope, including any exclusions or replacement arrangements.'),
1327:('Office plant rental and maintenance.','Office plant rental, thoughtfully placed and cared for. ANZ helps select, deliver and install plants suited to your workplace, with ongoing maintenance arranged around the space.','Plant selection|Delivery and placement|Watering, pruning and agreed care','What is included in office plant rental?','ANZ’s existing service describes plant selection, installation and ongoing maintenance. Confirm plant quantities, visit frequency, rental duration and replacement terms in your quote.'),
1329:('Planter sizes, finishes and placement.','FRP planters provide a way to introduce planting to interior and exterior spaces. Explore forms and finishes alongside the practical needs of your planting scheme.','Planter selection|Placement and planting|Drainage requirements','Can FRP planters be used outdoors?','Confirm the proposed product’s suitability, finish and drainage arrangement. Ask for the currently available sizes and options rather than relying on a fixed catalogue.')}
data=[]
for p in pages:
 i=p['id']; r=next(x for x in raw if x['id']==i)
 imgs=[str(x.get('id')) for x in p['images'] if str(x.get('id')) in available and not any(s in x['url'].lower() for s in ['card_','placeholder','logo','icon','reviews'])]
 if i in copy:
  c=copy[i]; data.append({'id':i,'path':p['path'],'kind':'service','title':html.unescape(p['title']),'headline':c[0],'intro':c[1],'scope':c[2].split('|'),'faq':[c[3],c[4]],'images':imgs[:2],'workplace':i in [1301,1323,1325,1327,1329],'variant':list(copy).index(i)%5})
 elif p['path'].startswith('/projects/') and i!=695:
  data.append({'id':i,'path':p['path'],'kind':'project','title':p['title'],'location':p['texts'][-1],'category':'Commercial' if 'Commercial' in p['texts'][0] else 'Residential','images':imgs,'intro':'A photographic look at '+p['title']+' from the ANZ project portfolio.'})
(T/'inc/catalogue.json').write_text(json.dumps(data,ensure_ascii=False,indent=2),encoding='utf8')
# Clean-room local seed only. Does not write to an existing production database.
seed=[]
for p in pages:
 r=next(x for x in raw if x['id']==p['id'])
 content=r['content']
 if p['id'] in [701,703,705,707]:
  content='\n'.join(n for n in p['texts'] if '<' in n) or next((n.get('settings',{}).get('editor','') for n in []),'')
  # Exact editor HTML lives in Elementor settings.
  def walk(ns):
   for n in ns:
    yield n
    yield from walk(n.get('elements',[]))
  content='\n'.join(n['settings']['editor'] for n in walk(r['elementor']) if isinstance(n.get('settings'),dict) and n['settings'].get('editor'))
  content=re.sub(r'https?://zinavo-clientupdates[^\"\s<>]+','/privacy-policy/',content)
 seed.append({'id':p['id'],'title':html.unescape(p['title']),'slug':r['slug'],'parent':r['parent'],'type':r['type'],'date':r['date'],'content':content})
(R/'content-migration/local-seed.json').write_text(json.dumps(seed,ensure_ascii=False),encoding='utf8')
print('Prepared',len(data),'service/project records and',len(seed),'local seed records')
